-- Definition only; no role or user grants and no default policy.
insert into permission_definitions(permission_key,module,label,description,protected) values
 ('commercial.invoice_batch.confirm','Commercial','Confirm downstream invoice billing','Record an explicit scoped human attestation for an exported invoice-ready artifact.',false);

create table invoice_batch_confirmations(
 id uuid primary key,organization_id text not null,legal_entity_id text not null,batch_id uuid not null unique references invoice_draft_batches(id),artifact_id uuid not null unique references invoice_csv_artifacts(id),artifact_version int not null check(artifact_version=1),artifact_sha256 text not null check(artifact_sha256~'^[a-f0-9]{64}$'),currency text not null check(currency~'^[A-Z]{3}$'),total numeric not null check(total>0),
 confirmation_kind text not null check(confirmation_kind='MANUAL_ATTESTATION'),external_reference text not null check(external_reference=btrim(external_reference) and length(external_reference) between 1 and 200 and external_reference !~ '[[:cntrl:]]'),actor_id uuid not null references users(id),active_role text not null,request_id uuid not null,request_fingerprint text not null check(request_fingerprint~'^[a-f0-9]{64}$'),reason text not null check(length(btrim(reason)) between 3 and 1000),operation_id text not null,confirmed_at timestamptz not null default clock_timestamp(),unique(organization_id,legal_entity_id,actor_id,request_id)
);
create trigger immutable_invoice_batch_confirmations before update or delete on invoice_batch_confirmations for each row execute function reject_commercial_draft_rewrite();

create or replace function invoice_batch_governed_state(batch uuid) returns text language plpgsql stable as $$
declare i invoice_batch_approval_instances;p invoice_batch_approval_policies;last_decision text;n int;begin
 if exists(select 1 from invoice_batch_confirmations where batch_id=batch) then return 'Billed/Confirmed';end if;
 if exists(select 1 from invoice_csv_artifacts where batch_id=batch) then return 'Exported';end if;
 if exists(select 1 from invoice_draft_cancellations where batch_id=batch) then return 'Cancelled';end if;
 select * into i from invoice_batch_approval_instances where batch_id=batch order by sequence desc limit 1;if i.id is null then return 'Draft';end if;
 select * into p from invoice_batch_approval_policies where id=i.policy_id;select count(*)::int into n from invoice_batch_approval_transitions where instance_id=i.id;select decision into last_decision from invoice_batch_approval_transitions where instance_id=i.id order by sequence desc limit 1;
 if last_decision='Approved' and n=jsonb_array_length(p.definition->'stages') then return 'Approved';end if;if last_decision='Rejected' or exists(select 1 from invoice_batch_approval_invalidations where instance_id=i.id) then return 'Draft';end if;return 'Under Review';
end $$;

create function guard_invoice_batch_confirmation() returns trigger language plpgsql as $$
declare ctx jsonb;b invoice_draft_batches;a invoice_csv_artifacts;l invoice_draft_lines;begin
 begin ctx=nullif(current_setting('workos.invoice_confirmation_context',true),'')::jsonb;exception when others then ctx=null;end;
 select * into b from invoice_draft_batches where id=new.batch_id for update;select * into a from invoice_csv_artifacts where id=new.artifact_id for share;perform lock_commercial_candidate_identity(new.organization_id,new.legal_entity_id,new.actor_id,new.active_role);
 if ctx is null or b.id is null or a.id is null or new.id::text is distinct from ctx->>'confirmationId' or new.organization_id is distinct from ctx->>'organizationId' or new.legal_entity_id is distinct from ctx->>'legalEntityId' or new.actor_id::text is distinct from ctx->>'actorId' or new.active_role is distinct from ctx->>'activeRole' or new.operation_id is distinct from ctx->>'operationId' or b.organization_id<>new.organization_id or b.legal_entity_id<>new.legal_entity_id or a.batch_id<>b.id or invoice_batch_governed_state(b.id)<>'Exported' or new.artifact_version<>a.version or new.artifact_sha256<>a.sha256 or new.artifact_sha256<>encode(digest(a.payload,'sha256'),'hex') or new.currency<>a.currency or new.total<>a.total or not invoice_csv_actor_valid(new.organization_id,new.legal_entity_id,new.actor_id,new.active_role,'view') or not invoice_notice_actor_has(new.organization_id,new.legal_entity_id,new.actor_id,new.active_role,'commercial.invoice_batch.confirm') then raise exception 'Exact exported artifact, scoped actor and confirmation authority are required.' using errcode='IBC01';end if;
 new.confirmed_at=clock_timestamp();for l in select * from invoice_draft_lines where batch_id=b.id order by sequence loop perform lock_tm_billing_worker_witness(b.organization_id,b.legal_entity_id,l.snapshot_id,new.actor_id,new.active_role);if not tm_billing_worker_visible(b.organization_id,b.legal_entity_id,l.snapshot_id,new.actor_id,new.active_role) then raise exception 'Current worker scope is required for every retained line.' using errcode='IBC01';end if;end loop;return new;
end $$;
create trigger guard_invoice_batch_confirmation before insert on invoice_batch_confirmations for each row execute function guard_invoice_batch_confirmation();

-- A later confirmation uses the same canonical informational template but has
-- its own source operation and immutable event identity; it never reuses the
-- already accepted export event.
alter table invoice_export_notice_events drop constraint invoice_export_notice_events_check;
alter table invoice_export_notice_events add column confirmation_id uuid references invoice_batch_confirmations(id) unique;
alter table invoice_export_notice_events add constraint invoice_export_notice_source_check check((event_key='invoice_batch.export_failed' and policy_class='OPERATIONAL_CRITICAL' and failure_id is not null and artifact_id is null and confirmation_id is null) or(event_key='invoice_batch.exported_or_billed_confirmed' and policy_class='INFORMATIONAL' and failure_id is null and ((artifact_id is not null and confirmation_id is null) or(artifact_id is null and confirmation_id is not null))));
alter table invoice_export_notice_producer_failures drop constraint invoice_export_notice_producer_failures_check;
alter table invoice_export_notice_producer_failures add column confirmation_id uuid references invoice_batch_confirmations(id) unique;
alter table invoice_export_notice_producer_failures add constraint invoice_export_notice_producer_source_check check((case when artifact_id is not null then 1 else 0 end)+(case when failure_id is not null then 1 else 0 end)+(case when confirmation_id is not null then 1 else 0 end)=1);

create or replace function guard_invoice_export_notice() returns trigger language plpgsql as $$
declare ctx jsonb;ev invoice_export_notice_events;b invoice_draft_batches;p invoice_export_notice_policies;t jsonb;src record;rel record;expected text[];pref boolean;decision text;rec invoice_export_notice_recipients;latest uuid;recovering boolean;begin
 begin ctx=nullif(current_setting('workos.invoice_notice_event_context',true),'')::jsonb;exception when others then ctx=null;end;
 if ctx is null then raise exception 'An exact protected notification operation is required.' using errcode='INC01';end if;
 if tg_table_name='invoice_export_notice_events' then
  select * into b from invoice_draft_batches where id=new.batch_id;select * into p from invoice_export_notice_policies where id=new.policy_id;
  if new.confirmation_id is not null then select id,batch_id,actor_id,active_role,operation_id into src from invoice_batch_confirmations where id=new.confirmation_id;elsif new.artifact_id is not null then select id,batch_id,actor_id,active_role,operation_id into src from invoice_csv_artifacts where id=new.artifact_id;else select id,batch_id,actor_id,active_role,operation_id into src from invoice_csv_failures where id=new.failure_id;end if;
  select id into latest from invoice_export_notice_policies where organization_id=b.organization_id and legal_entity_id=b.legal_entity_id and engagement_id=b.engagement_id and effective_from<=(clock_timestamp() at time zone 'UTC')::date order by effective_from desc,sequence desc limit 1;
  select exists(select 1 from invoice_export_notice_recoveries z join invoice_export_notice_producer_failures f on f.id=z.producer_failure_id where z.id::text=ctx->>'recoveryId' and z.batch_id=b.id and z.policy_id=p.id and z.actor_id::text=ctx->>'actorId' and z.active_role=ctx->>'activeRole' and (f.artifact_id=new.artifact_id or f.failure_id=new.failure_id or f.confirmation_id=new.confirmation_id) and invoice_csv_actor_valid(z.organization_id,z.legal_entity_id,z.actor_id,z.active_role,'view') and invoice_notice_actor_has(z.organization_id,z.legal_entity_id,z.actor_id,z.active_role,'commercial.invoice_export.recover_notices')) into recovering;
  select x into t from jsonb_array_elements(p.definition->'templates')x where x->>'key'=new.event_key;
  if b.id is null or p.id is null or src.id is null or t is null or new.id::text is distinct from ctx->>'eventId' or b.id::text is distinct from ctx->>'batchId' or p.id::text is distinct from ctx->>'policyId' or src.id::text is distinct from ctx->>'resultId' or (not recovering and (src.actor_id::text is distinct from ctx->>'actorId' or src.active_role is distinct from ctx->>'activeRole')) or src.operation_id is distinct from ctx->>'operationId' or new.operation_id<>src.operation_id or src.batch_id<>b.id or b.organization_id is distinct from ctx->>'organizationId' or b.legal_entity_id is distinct from ctx->>'legalEntityId' or p.organization_id<>b.organization_id or p.legal_entity_id<>b.legal_entity_id or p.engagement_id<>b.engagement_id or (not recovering and p.id is distinct from latest) or new.locale is distinct from p.definition->>'locale' or new.title is distinct from replace(t->>'subject','{{sourceRef}}','invoice-batch/'||b.id::text) or new.body is distinct from replace(t->>'body','{{sourceRef}}','invoice-batch/'||b.id::text) then raise exception 'Exact operation, current policy and sanitized event required.' using errcode='INC02';end if;return new;
 end if;
 if tg_table_name='invoice_export_notice_deliveries' then select * into rec from invoice_export_notice_recipients where id=new.recipient_id;select * into ev from invoice_export_notice_events where id=rec.event_id;else select * into ev from invoice_export_notice_events where id=new.event_id;end if;select * into b from invoice_draft_batches where id=ev.batch_id;select * into p from invoice_export_notice_policies where id=ev.policy_id;
 if ev.id is null or ev.id::text is distinct from ctx->>'eventId' or b.id::text is distinct from ctx->>'batchId' or p.id::text is distinct from ctx->>'policyId' or ev.operation_id is distinct from ctx->>'operationId' then raise exception 'Exact retained event is required.' using errcode='INC02';end if;
 if ctx ? 'recoveryId' and not exists(select 1 from invoice_export_notice_recoveries z left join invoice_export_notice_producer_failures f on f.id=z.producer_failure_id where z.id::text=ctx->>'recoveryId' and z.batch_id=b.id and z.policy_id=p.id and z.actor_id::text=ctx->>'actorId' and z.active_role=ctx->>'activeRole' and (z.event_id=ev.id or(f.artifact_id=ev.artifact_id or f.failure_id=ev.failure_id or f.confirmation_id=ev.confirmation_id)) and invoice_csv_actor_valid(z.organization_id,z.legal_entity_id,z.actor_id,z.active_role,'view') and invoice_notice_actor_has(z.organization_id,z.legal_entity_id,z.actor_id,z.active_role,'commercial.invoice_export.recover_notices')) then raise exception 'Current scoped recovery authority required.' using errcode='INC01';end if;
 if tg_table_name='invoice_export_alert_outbox' then
  if ev.event_key<>'invoice_batch.export_failed' or new.route_id<>p.route_id or new.status<>'Pending' then raise exception 'Exact configured operational route is required.' using errcode='INC02';end if;return new;
 elsif tg_table_name='invoice_export_notice_failures' then return new;
 elsif tg_table_name='invoice_export_notice_deliveries' then
  select * into rec from invoice_export_notice_recipients where id=new.recipient_id;
  if rec.id is null or not rec.in_app then raise exception 'Delivery must match its in-app recipient.' using errcode='INC02';end if;return new;
 end if;
 select array_agg(distinct x.recipient_reason order by x.recipient_reason) into expected from invoice_export_expected_recipients(ev)x where x.recipient=new.user_id;
 for rel in select * from invoice_export_expected_recipients(ev)x where x.recipient=new.user_id loop
  perform lock_commercial_candidate_identity(b.organization_id,b.legal_entity_id,rel.recipient,rel.held_role);
  if not invoice_notice_named_recipient(b.organization_id,b.legal_entity_id,rel.recipient,rel.held_role) or (rel.recipient_reason='finance_billing_owner' and (not invoice_draft_actor_valid(b.organization_id,b.legal_entity_id,rel.recipient,rel.held_role,'view') or exists(select 1 from invoice_draft_lines l where l.batch_id=b.id and not tm_billing_worker_visible(b.organization_id,b.legal_entity_id,l.snapshot_id,rel.recipient,rel.held_role)))) then raise exception 'Current scoped notification recipient required.' using errcode='INC01';end if;
 end loop;
 select n.in_app into pref from notification_preferences n join users u on u.employee_record_id=n.employee_id where u.id=new.user_id and n.event_type=ev.event_key for share of n;
 decision=case when ev.event_key='invoice_batch.export_failed' then 'Required' when not(p.definition->>'completionInApp')::boolean then 'SuppressedPolicy' when pref is false then 'SuppressedPreference' else 'Enabled' end;
 if expected is null or (select array_agg(x order by x) from unnest(new.reasons)x) is distinct from expected or new.channel_decision<>decision or new.in_app is distinct from(decision in('Required','Enabled')) then raise exception 'Exact recipient reasons and channel policy required.' using errcode='INC02';end if;return new;
end $$;

create or replace function guard_invoice_export_notice_producer_failure() returns trigger language plpgsql as $$
declare ctx jsonb;b invoice_draft_batches;p invoice_export_notice_policies;src record;begin
 begin ctx=nullif(current_setting('workos.invoice_notice_event_context',true),'')::jsonb;exception when others then ctx=null;end;
 select * into b from invoice_draft_batches where id=new.batch_id;select * into p from invoice_export_notice_policies where id=new.policy_id;
 if new.confirmation_id is not null then select id,batch_id,actor_id,active_role,operation_id into src from invoice_batch_confirmations where id=new.confirmation_id;elsif new.artifact_id is not null then select id,batch_id,actor_id,active_role,operation_id into src from invoice_csv_artifacts where id=new.artifact_id;else select id,batch_id,actor_id,active_role,operation_id into src from invoice_csv_failures where id=new.failure_id;end if;
 if ctx is null or b.id is null or p.id is null or src.id is null or b.id::text is distinct from ctx->>'batchId' or p.id::text is distinct from ctx->>'policyId' or src.id::text is distinct from ctx->>'resultId' or src.actor_id::text is distinct from ctx->>'actorId' or src.active_role is distinct from ctx->>'activeRole' or src.operation_id is distinct from ctx->>'operationId' or new.operation_id<>src.operation_id or src.batch_id<>b.id or b.organization_id is distinct from ctx->>'organizationId' or b.legal_entity_id is distinct from ctx->>'legalEntityId' or p.organization_id<>b.organization_id or p.legal_entity_id<>b.legal_entity_id or p.engagement_id<>b.engagement_id or exists(select 1 from invoice_export_notice_events ev where (new.artifact_id is not null and ev.artifact_id=new.artifact_id) or (new.failure_id is not null and ev.failure_id=new.failure_id) or (new.confirmation_id is not null and ev.confirmation_id=new.confirmation_id)) then raise exception 'Exact operation and visible isolated notification failure required.' using errcode='INC02';end if;return new;
end $$;

create or replace function guard_invoice_export_notice_recovery() returns trigger language plpgsql as $$
declare ctx jsonb;b invoice_draft_batches;ev invoice_export_notice_events;f invoice_export_notice_producer_failures;begin
 begin ctx=nullif(current_setting('workos.invoice_notice_recovery_context',true),'')::jsonb;exception when others then ctx=null;end;
 select * into b from invoice_draft_batches where id=new.batch_id for update;perform lock_commercial_candidate_identity(new.organization_id,new.legal_entity_id,new.actor_id,new.active_role);
 if ctx is null or b.id is null or new.id::text is distinct from ctx->>'recoveryId' or new.actor_id::text is distinct from ctx->>'actorId' or new.active_role is distinct from ctx->>'activeRole' or new.operation_id is distinct from ctx->>'operationId' or new.organization_id is distinct from ctx->>'organizationId' or new.legal_entity_id is distinct from ctx->>'legalEntityId' or b.organization_id<>new.organization_id or b.legal_entity_id<>new.legal_entity_id or not invoice_csv_actor_valid(new.organization_id,new.legal_entity_id,new.actor_id,new.active_role,'view') or not invoice_notice_actor_has(new.organization_id,new.legal_entity_id,new.actor_id,new.active_role,'commercial.invoice_export.recover_notices') or exists(select 1 from invoice_draft_lines l where l.batch_id=b.id and not tm_billing_worker_visible(b.organization_id,b.legal_entity_id,l.snapshot_id,new.actor_id,new.active_role)) then raise exception 'Current scoped notice recovery authority is required.' using errcode='INC01';end if;
 if new.event_id is not null then select * into ev from invoice_export_notice_events where id=new.event_id;if ev.id is null or ev.batch_id<>b.id or ev.policy_id<>new.policy_id or not exists(select 1 from invoice_export_notice_failures where event_id=ev.id) then raise exception 'An incomplete retained event is required.' using errcode='INC02';end if;
 else select * into f from invoice_export_notice_producer_failures where id=new.producer_failure_id;if f.id is null or f.batch_id<>b.id or f.policy_id<>new.policy_id or exists(select 1 from invoice_export_notice_events e where (f.artifact_id is not null and e.artifact_id=f.artifact_id) or (f.failure_id is not null and e.failure_id=f.failure_id) or (f.confirmation_id is not null and e.confirmation_id=f.confirmation_id)) then raise exception 'An incomplete retained event operation is required.' using errcode='INC02';end if;end if;
 return new;
end $$;

create or replace function complete_invoice_export_notice_recovery() returns trigger language plpgsql as $$
declare ev invoice_export_notice_events;f invoice_export_notice_producer_failures;expected integer;actual integer;begin
 if not invoice_csv_actor_valid(new.organization_id,new.legal_entity_id,new.actor_id,new.active_role,'view') or not invoice_notice_actor_has(new.organization_id,new.legal_entity_id,new.actor_id,new.active_role,'commercial.invoice_export.recover_notices') or exists(select 1 from invoice_draft_lines l where l.batch_id=new.batch_id and not tm_billing_worker_visible(new.organization_id,new.legal_entity_id,l.snapshot_id,new.actor_id,new.active_role)) or not exists(select 1 from audit_logs a where a.organization_id=new.organization_id and a.legal_entity_id=new.legal_entity_id and a.user_id=new.actor_id::text and a.active_role=new.active_role and a.module='Invoice Export Notifications' and a.action='Attempt Notice Recovery' and a.entity_id=new.id::text and a.operation_id=new.operation_id and a.new_value=jsonb_build_object('recoveryId',new.id,'batchId',new.batch_id,'eventId',new.event_id,'producerFailureId',new.producer_failure_id)) then raise exception 'Recovery authority and sanitized audit must persist through commit.' using errcode='INC03';end if;
 if new.event_id is not null then select * into ev from invoice_export_notice_events where id=new.event_id;else select * into f from invoice_export_notice_producer_failures where id=new.producer_failure_id;select * into ev from invoice_export_notice_events where (f.artifact_id is not null and artifact_id=f.artifact_id) or (f.failure_id is not null and failure_id=f.failure_id) or (f.confirmation_id is not null and confirmation_id=f.confirmation_id);end if;
 if ev.id is not null then select count(distinct recipient)::int into expected from invoice_export_expected_recipients(ev);select count(*)::int into actual from invoice_export_notice_recipients where event_id=ev.id;if actual not in(0,expected) or exists(select 1 from invoice_export_notice_recipients r where r.event_id=ev.id and r.in_app and not exists(select 1 from invoice_export_notice_deliveries d where d.recipient_id=r.id and d.status='Delivered')) then raise exception 'Recovery cannot commit a partial recipient set.' using errcode='INC03';end if;end if;return null;
end $$;

create function complete_invoice_batch_confirmation() returns trigger language plpgsql as $$
declare b invoice_draft_batches;a invoice_csv_artifacts;begin
 select * into b from invoice_draft_batches where id=new.batch_id;select * into a from invoice_csv_artifacts where id=new.artifact_id;
 if b.id is null or a.id is null or invoice_batch_governed_state(b.id)<>'Billed/Confirmed' or a.batch_id<>b.id or new.artifact_version<>a.version or new.artifact_sha256<>a.sha256 or new.artifact_sha256<>encode(digest(a.payload,'sha256'),'hex') or new.currency<>a.currency or new.total<>a.total or exists(select 1 from invoice_draft_cancellations where batch_id=b.id) or exists(select 1 from invoice_draft_lines l where l.batch_id=b.id and not exists(select 1 from invoice_draft_occupancies o where o.batch_id=b.id and o.line_id=l.id and o.item_id=l.item_id and o.item_version=l.item_version)) or not invoice_csv_actor_valid(new.organization_id,new.legal_entity_id,new.actor_id,new.active_role,'view') or not invoice_notice_actor_has(new.organization_id,new.legal_entity_id,new.actor_id,new.active_role,'commercial.invoice_batch.confirm') or exists(select 1 from invoice_draft_lines l where l.batch_id=b.id and not tm_billing_worker_visible(b.organization_id,b.legal_entity_id,l.snapshot_id,new.actor_id,new.active_role)) then raise exception 'Confirmation, immutable artifact, occupancy and current scope must commit together.' using errcode='IBC02';end if;
 if not exists(select 1 from audit_logs x where x.organization_id=b.organization_id and x.legal_entity_id=b.legal_entity_id and x.user_id=new.actor_id::text and x.active_role=new.active_role and x.module='Invoice Billing Confirmation' and x.action='Record Manual Attestation' and x.entity_id=new.id::text and x.operation_id=new.operation_id and x.new_value=jsonb_build_object('confirmationId',new.id,'batchId',b.id,'artifactId',a.id,'sha256',a.sha256)) then raise exception 'Confirmation and sanitized audit must commit together.' using errcode='IBC02';end if;
 if not exists(select 1 from invoice_export_notice_events x where x.confirmation_id=new.id and x.batch_id=b.id and x.operation_id=new.operation_id and x.event_key='invoice_batch.exported_or_billed_confirmed') and not exists(select 1 from invoice_export_notice_producer_failures x where x.confirmation_id=new.id and x.batch_id=b.id and x.operation_id=new.operation_id) then raise exception 'Confirmation requires the canonical event or visible recovery evidence.' using errcode='IBC02';end if;return null;
end $$;
create constraint trigger complete_invoice_batch_confirmation after insert on invoice_batch_confirmations deferrable initially deferred for each row execute function complete_invoice_batch_confirmation();
